head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 사전 조건 : Body 데이터 2행 세팅(그리드 표시용). Footer 셀 초기값은 value 속성으로 부여됨.
scwin.onpageload = function () {
    dlt_bind.setJSON([
        { c0: "a1", c1: "b1", c2: "c1", c3: "d1", c4: "e1", c5: "f1" },
        { c0: "a2", c1: "b2", c2: "c2", c3: "d2", c4: "e2", c5: "f2" }
    ], false);
};



// 대상 Footer Cell 6종 (인덱스/ID/dataType/적용 마스크) : number 외 숫자형(float/bigDecimal)까지 포함
scwin.CASES = [
    { idx: 0, id: "fnum",    type: "number",     fmt: "#,##0.00" },
    { idx: 1, id: "ffloat",  type: "float",      fmt: "#,##0.00" },
    { idx: 2, id: "fbigdec", type: "bigDecimal", fmt: "#,##0.00" },
    { idx: 3, id: "ftext",   type: "text",       fmt: "###-####" },
    { idx: 4, id: "fdate",   type: "date",       fmt: "yyyy-MM-dd" },
    { idx: 5, id: "ftime",   type: "time",       fmt: "HH:mm:ss" }
];

// Footer 셀의 화면 표시값(td textContent) 조회
scwin.footerTdText = function (footerId) {
    var td = document.querySelector("[id$='target1_" + footerId + "']");
    return td ? td.textContent.trim() : "(no td)";
};



// [결함 자동 재현] 6개 dataType Footer 셀에 setFooterDisplayFormat 적용 후,
//  formatter 반영값(getFooterData 'displayData') vs 화면 표시값(td) 대조
scwin.btn_reproduce_onclick = function () {
    scwin.btn_clear_onclick();

    // 각 Footer 셀에 dataType 에 맞는 displayFormat 적용
    scwin.CASES.forEach(function (c) {
        target1.setFooterDisplayFormat(c.idx, c.fmt);
    });

    setTimeout(function () {
        scwin.CASES.forEach(function (c) {
            var dd = target1.getFooterData(c.idx, "displayData"); // formatter 반영값
            var td = scwin.footerTdText(c.id);                    // 화면 표시값
            var mark = (dd === td) ? "화면반영 O" : "화면반영 X (formatter 만 갱신)";
            scwin.setReturnValue("[" + c.type + "] setFooterDisplayFormat(" + c.idx + ", '" + c.fmt + "')  ->  getFooterData=" + dd + "  /  화면표시값=" + td + "   => " + mark);
        });
        scwin.setReturnValue("");
        scwin.setReturnValue("[기대] number/float/bigDecimal/text/date/time 모두 화면(td)에 displayFormat 반영 (가이드 @param 마스크 명시)");
        scwin.setReturnValue("[실제] dataType='number' 인 셀만 화면 반영. float/bigDecimal/text/date/time 은 formatter(데이터)만 갱신되고 화면 td 미반영 => 결함 (통화형 euro/rupee 등도 동일하게 미반영)");
    }, 300);
};
